# Install packages not pre-loaded on Kaggle
install_if_missing <- function(pkgs) {
  for (pkg in pkgs) {
    if (!requireNamespace(pkg, quietly = TRUE)) {
      cat(sprintf("  Installing: %s\n", pkg))
      install.packages(pkg, quiet = TRUE, dependencies = TRUE)
    } else {
      cat(sprintf("  Ready: %s\n", pkg))
    }
  }
}

options(repos = c(CRAN = "https://cran.rstudio.com/"))

install_if_missing(c(
  "tidyverse", "ggplot2", "patchwork", "scales",
  "ggcorrplot", "viridis",
  "tidymodels", "recipes", "parsnip", "workflows",
  "tune", "yardstick", "rsample", "dials", "hardhat",
  "ranger", "xgboost", "glmnet",
  "themis", "shapviz", "vip"
))

cat("\n All packages ready.\n")
